-- Run against the migrated local/isolated database. All synthetic records roll back.
begin;
create function pg_temp.support_check(value boolean,label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'Support check failed: %',label;end if;perform set_config('lumo.support_checks',(coalesce(nullif(current_setting('lumo.support_checks',true),''),'0')::int+1)::text,true);end $$;
do $test$
#variable_conflict use_variable
declare actor uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();customer uuid:=gen_random_uuid();customer_sid uuid:=gen_random_uuid();other uuid:=gen_random_uuid();other_sid uuid:=gen_random_uuid();merchant uuid:=gen_random_uuid();account_id uuid:=gen_random_uuid();cid uuid;mcid uuid;privacy_case uuid;rev bigint;out jsonb;payload jsonb;initial_state jsonb;business jsonb;attempted boolean:=false;before_count bigint;
begin
 perform set_config('lumo.support_checks','0',true);
 insert into auth.users(id,email) values(actor,'support-local@example.test'),(customer,'customer-local@example.test'),(other,'other-local@example.test');
 insert into auth.sessions(id,user_id) values(sid,actor),(customer_sid,customer),(other_sid,other);
 insert into lumo_private.admin_staff(user_id,display_name,email,role) values(actor,'Local support','support-local@example.test','supervisor');
 insert into lumo_private.profiles(user_id,handle,display_name,pin_hash) values(customer,'support_'||substr(replace(customer::text,'-',''),1,12),'Local customer','fixture'),(other,'support_'||substr(replace(other::text,'-',''),1,12),'Other customer','fixture');
 insert into lumo_private.accounts(id,owner_user_id,kind) values(account_id,customer,'merchant');
 insert into lumo_private.merchants(id,owner_user_id,account_id,name) values(merchant,customer,account_id,'Local merchant');
 payload:=jsonb_build_object('actor',actor,'session',sid);
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 initial_state:=jsonb_build_object('account',jsonb_build_object('supportCases',jsonb_build_array(jsonb_build_object('id','case-1','reference','LUM-00001','title','Help with a payment','body','Original public issue','createdAt',clock_timestamp(),'status','open','updates','[]'::jsonb)),'requests','[]'::jsonb));
 insert into lumo_private.approved_states(user_id,state) values(customer,initial_state);
 select id into cid from lumo_private.admin_cases where source_id='consumer:'||customer::text||':case-1';
 perform pg_temp.support_check(cid is not null,'consumer report enters queue');
 perform pg_temp.support_check((select source_reference from lumo_private.admin_cases where id=cid)='LUM-00001','legacy reference retained');
 update lumo_private.admin_cases set assignee_id=actor where id=cid;
 out:=public.lumo_admin_service('cases.note',payload||jsonb_build_object('id',cid,'body','Private staff note'));
 perform pg_temp.support_check(out->>'ok'='true','private note saved');
 select revision into rev from lumo_private.admin_cases where id=cid;
 out:=public.lumo_admin_service('cases.update',payload||jsonb_build_object('id',cid,'revision',rev,'status','resolved','resolution','Public issue reviewed','customerUpdate','Please confirm this fixed it.'));
 perform pg_temp.support_check(out->>'ok'='true','support resolves report');
 perform pg_temp.support_check((select state#>>'{account,supportCases,0,status}' from lumo_private.approved_states where user_id=customer)='resolved','staff result appears in consumer source');
 perform pg_temp.support_check((select count(*) from lumo_private.admin_case_messages where case_id=cid and author_kind='support')=1,'one outbound message without recursive duplicate');
 update lumo_private.approved_states set state=jsonb_set(jsonb_set(state,'{account,supportCases,0,status}','"open"'),'{account,supportCases,0,updates}',state#>'{account,supportCases,0,updates}'||jsonb_build_array(jsonb_build_object('id','reply-1','kind','you','text','The issue is still present','at',clock_timestamp()))),revision=revision+1 where user_id=customer;
 perform pg_temp.support_check((select status from lumo_private.admin_cases where id=cid)='open','consumer reply reopens resolved support case');
 perform pg_temp.support_check((select assignee_id from lumo_private.admin_cases where id=cid)=actor,'reopen preserves assigned support owner');
 perform pg_temp.support_check((select count(*) from lumo_private.admin_case_notes where case_id=cid)=1,'reopen preserves private notes');
 perform pg_temp.support_check((select count(*) from lumo_private.admin_case_messages where case_id=cid and body='The issue is still present')=1,'new consumer note is visible once');
 select revision into rev from lumo_private.admin_cases where id=cid;
 perform lumo_private.admin_project_consumer_cases(customer,(select state from lumo_private.approved_states where user_id=customer),clock_timestamp());
 perform pg_temp.support_check((select revision from lumo_private.admin_cases where id=cid)=rev,'same snapshot replay leaves revision unchanged');
 out:=public.lumo_admin_service('cases.get',payload||jsonb_build_object('id',cid));
 perform pg_temp.support_check(out->>'ok'='true' and jsonb_array_length(out#>'{data,messages}')=3,'admin sees initial issue, public support and new consumer note');
 perform pg_temp.support_check(out::text like '%Private staff note%' and (select state::text not like '%Private staff note%' from lumo_private.approved_states where user_id=customer),'private notes stay out of consumer state');
 out:=public.lumo_admin_service('cases.list',payload||jsonb_build_object('q','LUM-00001'));
 perform pg_temp.support_check((out#>>'{data,total}')::int=1,'legacy source reference searchable');
 out:=public.lumo_case_inbox(jsonb_build_object('actor',customer,'session',customer_sid,'audience','consumer','operation','case','caseId',cid));
 perform pg_temp.support_check(out#>>'{case,source,type}'='consumer_support' and out#>>'{case,source,id}'='case-1','owner gets exact safe reply source');
 out:=public.lumo_case_inbox(jsonb_build_object('actor',other,'session',other_sid,'audience','consumer','operation','case','caseId',cid));
 perform pg_temp.support_check(out->>'code'='NOT_FOUND','another consumer cannot retrieve descriptor');
 out:=public.lumo_admin_service('cases.update',payload||jsonb_build_object('id',cid,'status','waiting_customer','customerUpdate','One more detail please'));
 update lumo_private.approved_states set state=jsonb_set(state,'{account,supportCases,0,updates}',state#>'{account,supportCases,0,updates}'||jsonb_build_array(jsonb_build_object('id','reply-2','kind','you','text','Here is the extra detail','at',clock_timestamp()))),revision=revision+1 where user_id=customer;
 perform pg_temp.support_check((select status from lumo_private.admin_cases where id=cid)='in_progress','reply leaves waiting-customer queue');
 perform set_config('lumo.source_backfill','on',true);
 update lumo_private.admin_cases set status='resolved',resolution='History reviewed',resolved_at=clock_timestamp() where id=cid;
 update lumo_private.approved_states set state=jsonb_set(state,'{account,supportCases,0,updates}',state#>'{account,supportCases,0,updates}'||jsonb_build_array(jsonb_build_object('id','old-history-only','kind','you','text','A historical message imported during backfill','at',clock_timestamp()-interval '3 days'))),revision=revision+1 where user_id=customer;
 perform pg_temp.support_check((select status from lumo_private.admin_cases where id=cid)='resolved','imported historical replies do not reopen resolved work');
 perform set_config('lumo.source_backfill','',true);
 business:=jsonb_build_object('business',jsonb_build_object('id',merchant),'tickets',jsonb_build_array(jsonb_build_object('id','merchant-case-1','subject','Counter issue','message','Original merchant issue','status','open','createdByName','Cashier fixture','createdByRole','cashier','counterId','counter-fixture','shiftId','shift-fixture','createdAt',clock_timestamp())));
 update lumo_private.approved_merchant_network set document=jsonb_set(document,array['businesses',merchant::text],business),revision=revision+1 where id;
 select id into mcid from lumo_private.admin_cases where source_id='merchant:'||merchant::text||':merchant-case-1';
 perform pg_temp.support_check(mcid is not null,'merchant report enters support queue');
 perform pg_temp.support_check((select source_context->>'createdByRole' from lumo_private.admin_cases where id=mcid)='cashier','server creator context retained');
 out:=public.lumo_admin_service('cases.update',payload||jsonb_build_object('id',mcid,'status','resolved','resolution','Counter reviewed','customerUpdate','Please check the counter.'));
 perform pg_temp.support_check(out->>'ok'='true','support resolves merchant case');
 update lumo_private.approved_merchant_network set document=jsonb_set(document,array['businesses',merchant::text,'tickets','0','responses'],document#>array['businesses',merchant::text,'tickets','0','responses']||jsonb_build_array(jsonb_build_object('id','merchant-reply-1','message','Counter still affected','by','owner-fixture','createdAt',clock_timestamp()))),revision=revision+1 where id;
 perform pg_temp.support_check((select status from lumo_private.admin_cases where id=mcid)='open','merchant reply reopens resolved case');
 perform pg_temp.support_check((select count(*) from lumo_private.admin_case_messages where case_id=mcid and author_kind='merchant')=2,'merchant initial and reply available');
 update lumo_private.approved_states set state=jsonb_set(state,'{account,requests}',jsonb_build_array(jsonb_build_object('id','privacy-1','type','deletion','status','requested','at',clock_timestamp()))),revision=revision+1 where user_id=customer;
 select id into privacy_case from lumo_private.admin_cases where source_id='privacy:'||customer::text||':privacy-1';
 perform pg_temp.support_check(privacy_case is not null,'privacy request has queue record, due time and identity');
 out:=public.lumo_admin_service('cases.update',payload||jsonb_build_object('id',privacy_case,'status','in_progress','assigneeId',actor,'customerUpdate','Your request is under review.'));
 perform pg_temp.support_check(out->>'ok'='true' and (select state#>>'{account,requests,0,reviewStatus}' from lumo_private.approved_states where user_id=customer)='in_progress','assigned privacy review progress reaches consumer');
 out:=public.lumo_admin_service('cases.update',payload||jsonb_build_object('id',privacy_case,'status','resolved','resolution','Retention reviewed. No records erased.','customerUpdate','The review is complete; retained financial records are unchanged.'));
 perform pg_temp.support_check(out->>'ok'='true' and (select state#>>'{account,requests,0,erasureExecuted}' from lumo_private.approved_states where user_id=customer)='false','review completion never claims erasure');
 perform pg_temp.support_check((select state#>>'{account,requests,0,status}' from lumo_private.approved_states where user_id=customer)='reviewed','completed review leaves requested state explicitly');
 update lumo_private.approved_states set state=jsonb_set(state,'{account,requests}',state#>'{account,requests}'||jsonb_build_array(jsonb_build_object('id','privacy-2','type','deletion','status','requested','at',clock_timestamp()))),revision=revision+1 where user_id=customer;
 update lumo_private.approved_states set state=jsonb_set(state,'{account,requests,1,status}','"cancelled"'),revision=revision+1 where user_id=customer;
 perform pg_temp.support_check((select status from lumo_private.admin_cases where source_id='privacy:'||customer::text||':privacy-2')='closed','source cancellation closes review without erasure');
 begin update lumo_private.admin_case_messages set body='tampered' where case_id=cid;exception when others then attempted:=true;end;
 perform pg_temp.support_check(attempted,'message stream rejects rewriting');
 perform pg_temp.support_check(not has_table_privilege('anon','lumo_private.admin_case_messages','select') and not has_table_privilege('authenticated','lumo_private.admin_case_messages','select'),'message storage remains private');
 perform pg_temp.support_check(strpos(pg_get_functiondef('public.lumo_admin_service(text,jsonb)'::regprocedure),'perform lumo_private.admin_lock_case_source(uid);select * into case_row')>0,'staff updates lock source before case');
end $test$;
select current_setting('lumo.support_checks')::integer as checks;
rollback;
